insert into public.forms (slug, title, description, schema, updated_by) values ('actividades-ia-2026', 'Identificación de actividades y uso de IA', 'Ayúdenos a identificar las actividades de su cargo y dónde la inteligencia artificial podría apoyarlas. Toma unos 10 minutos.', '{"gracias":"Su información nos ayudará a identificar dónde la inteligencia artificial puede ahorrar tiempo y mejorar el trabajo en el FNG.","campos":[{"id":"s_datos","tipo":"seccion","etiqueta":"1. Sus datos","ayuda":"Nos permiten agrupar las respuestas por área y cargo.","requerido":false,"opciones":"","max":5},{"id":"nombre","tipo":"texto","etiqueta":"Nombre completo","ayuda":"","requerido":true,"opciones":"","max":5},{"id":"correo","tipo":"correo","etiqueta":"Correo institucional","ayuda":"Solo para contactarle si hay dudas sobre sus respuestas.","requerido":true,"opciones":"","max":5},{"id":"area","tipo":"lista","etiqueta":"Área o dependencia","ayuda":"","requerido":true,"opciones":"Dirección Administrativa y Financiera\nDirección Jurídica\nDirección Técnica\nOficina de Planeación y Estudios Económicos\nOficina de Promoción y Divulgación\nSubdirección CTeI\nSubdirección Finanzas y Adquisiciones\nSubdirección Gestión Humana\nSubdirección de Operación y Logística\nSubdirección de Recaudo y Cartera\nSubdirección de Salud y Bienestar Animal\nSubdirección de Tecnología\nPresidencia Ejecutiva\nOtra","max":5},{"id":"cargo","tipo":"texto","etiqueta":"Cargo","ayuda":"Tal como aparece en su perfil de cargo 2026.","requerido":true,"opciones":"","max":5},{"id":"s_act","tipo":"seccion","etiqueta":"2. Actividades que realiza","ayuda":"Registre una fila por actividad: tanto las de su perfil de cargo como las adicionales que hace en su día a día.","requerido":false,"opciones":"","max":5},{"id":"actividades","tipo":"tabla","etiqueta":"Actividades","ayuda":"","requerido":true,"opciones":"","max":5,"columnas":[{"id":"actividad","etiqueta":"Actividad que realiza","tipo":"parrafo","opciones":"","requerido":true},{"id":"perfil","etiqueta":"¿Está en su perfil de cargo?","tipo":"lista","opciones":"Sí\nNo\nNo estoy seguro","requerido":true},{"id":"frecuencia","etiqueta":"¿Con qué frecuencia la hace?","tipo":"lista","opciones":"Diaria\nSemanal\nQuincenal\nMensual\nOcasional","requerido":false},{"id":"horas","etiqueta":"Horas al mes (aprox.)","tipo":"numero","opciones":"","requerido":false},{"id":"ia","etiqueta":"¿Puede hacerse con IA?","tipo":"lista","opciones":"Sí, totalmente\nSí, en parte\nNo\nNo sé","requerido":true},{"id":"logro","etiqueta":"¿Qué se lograría con IA?","tipo":"lista","opciones":"Ahorrar tiempo\nReducir errores\nMejorar la calidad\nAnalizar mejor los datos\nResponder más rápido\nOtro","requerido":false},{"id":"solucion","etiqueta":"Tipo de solución","tipo":"lista","opciones":"IA generativa / documentos\nAutomatización de flujos (n8n)\nRPA / ERP\nBI / analítica\nValidación automática (reglas)\nPersona con copiloto de IA\nNo sé","requerido":false},{"id":"herramienta","etiqueta":"Herramienta de IA sugerida","tipo":"texto","opciones":"","requerido":false},{"id":"como","etiqueta":"¿Cómo la utilizaría?","tipo":"parrafo","opciones":"","requerido":false},{"id":"obs","etiqueta":"Observaciones","tipo":"parrafo","opciones":"","requerido":false}]},{"id":"s_uso","tipo":"seccion","etiqueta":"3. Su experiencia con IA","ayuda":"","requerido":false,"opciones":"","max":5},{"id":"usa","tipo":"opcion","etiqueta":"¿Usa hoy alguna herramienta de IA en su trabajo?","ayuda":"","requerido":true,"opciones":"Sí\nNo","max":5},{"id":"cuales","tipo":"casillas","etiqueta":"¿Cuáles usa?","ayuda":"","requerido":false,"opciones":"ChatGPT\nMicrosoft Copilot\nGoogle Gemini\nClaude\nHerramientas de imagen o video\nOtra","max":5,"si":{"campo":"usa","op":"es","valor":"Sí"}},{"id":"frec_uso","tipo":"opcion","etiqueta":"¿Con qué frecuencia la usa?","ayuda":"","requerido":false,"opciones":"Todos los días\nAlgunas veces por semana\nDe vez en cuando","max":5,"si":{"campo":"usa","op":"es","valor":"Sí"}},{"id":"nivel","tipo":"escala","etiqueta":"¿Cómo califica su conocimiento sobre IA?","ayuda":"1 = ninguno · 5 = avanzado","requerido":true,"opciones":"","max":5},{"id":"barreras","tipo":"casillas","etiqueta":"¿Qué le impide usar más la IA?","ayuda":"","requerido":false,"opciones":"Falta de capacitación\nNo tengo licencias o acceso\nDudas sobre seguridad y confidencialidad\nFalta de tiempo\nNo sé por dónde empezar\nNada, ya la uso lo suficiente","max":5},{"id":"capacitacion","tipo":"opcion","etiqueta":"¿Le gustaría recibir capacitación en IA?","ayuda":"","requerido":true,"opciones":"Sí\nNo\nTal vez","max":5},{"id":"comentarios","tipo":"parrafo","etiqueta":"Comentarios o ideas adicionales","ayuda":"","requerido":false,"opciones":"","max":5}]}'::jsonb, 'claude') on conflict (slug) do nothing returning id;
